INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(389, 1, 'Ragefire Chasm', 'rfc,ragefire,ragefire chasm', '', 'Oggleflint', 'oggleflint', 'Trogg chief with a couple of troggs around him. A plain fight: clear his friends, then him.', 'Pull him with his troggs and keep them all on you.', 'Light damage, keep the tank up.', 'Kill the troggs first if they go for the healer, then Oggleflint.'),
(389, 2, 'Ragefire Chasm', 'rfc,ragefire,ragefire chasm', '', 'Taragaman the Hungerer', 'taragaman', 'Big demon: Fire Nova burns everyone near him and Uppercut knocks the tank away.', 'Back him into a wall so Uppercut doesn''t throw you far, and get straight back in after one.', 'Fire Nova hits all the melee: heal through it, stay at range.', 'Casters and hunters stay out of Fire Nova range; melee keep their health up.'),
(389, 3, 'Ragefire Chasm', 'rfc,ragefire,ragefire chasm', '', 'Jergosh the Invoker', 'jergosh', 'Caster: Immolate on someone and Curse of Weakness on the tank.', 'Pull him round a corner so he comes into melee.', 'Heal through Immolate; mages and druids remove his curse.', 'Interrupt his casts and burn him.'),
(389, 4, 'Ragefire Chasm', 'rfc,ragefire,ragefire chasm', '', 'Bazzalan', 'bazzalan', 'Satyr rogue: Sinister Strike and poison on the tank.', 'Plain tank and spank.', 'Cure the poison on the tank.', 'Burn him.'),
(43, 1, 'Wailing Caverns', 'wc,wailing caverns', '', 'Lady Anacondra', 'anacondra', 'Druid of the Fang: Lightning Bolt, Sleep on one of us, and Healing Touch on herself.', 'Pull her out of sight round a corner so she comes to you.', 'Dispel the Sleep if you can, heal the bolts.', 'Interrupt every Healing Touch, then burn her.'),
(43, 2, 'Wailing Caverns', 'wc,wailing caverns', '', 'Lord Cobrahn', 'cobrahn', 'Lightning Bolt and Sleep, poisons, and at low health he turns into a big serpent that hits much harder.', 'Keep him in melee; be ready for the serpent form near the end.', 'Cure the poison and save mana for his serpent form.', 'Interrupt his heals and burn him fast once he changes form.'),
(43, 3, 'Wailing Caverns', 'wc,wailing caverns', '', 'Lord Pythas', 'pythas', 'Lightning Bolt, Sleep and Healing Touch, and a Thunderclap on the melee.', 'Keep him in melee, face him away from the casters.', 'Dispel Sleep, heal the Thunderclap damage.', 'Interrupt Healing Touch every time.'),
(43, 4, 'Wailing Caverns', 'wc,wailing caverns', '', 'Lord Serpentis', 'serpentis', 'The last Fanglord: Lightning Bolt, Sleep and Healing Touch.', 'Pull him away from the other druids.', 'Dispel Sleep on whoever he puts down.', 'Interrupt his heals.'),
(43, 5, 'Wailing Caverns', 'wc,wailing caverns', '', 'Kresh', 'kresh', 'Big turtle in the water. Harmless, kill it or swim past.', 'Plain tank and spank.', 'Little damage.', 'Burn it.'),
(43, 6, 'Wailing Caverns', 'wc,wailing caverns', '', 'Skum', 'skum', 'Thunder lizard in the water: Chained Bolt jumps between players standing close.', 'Keep him on you.', 'Heal the bolts.', 'Ranged spread out so the bolt doesn''t chain.'),
(43, 7, 'Wailing Caverns', 'wc,wailing caverns', '', 'Verdan the Everliving', 'verdan', 'Giant plant: Grasping Vines knock down everyone near him.', 'Keep him on you and expect to be knocked down.', 'Stay out of the vines'' reach, heal the tank.', 'Ranged keep their distance; melee heal up between knockdowns.'),
(43, 8, 'Wailing Caverns', 'wc,wailing caverns', '', 'Mutanus the Devourer', 'mutanus', 'Comes after the waves of Naralex''s awakening. Terrify fears, Naralex''s Nightmare sleeps, Thundercrack stuns.', 'Keep him on you through the fear; Berserker Rage or Tremor help.', 'Dispel the Nightmare sleep, keep the tank up during fears.', 'Burn him, he is the end of the dungeon.'),
(43, 9, 'Wailing Caverns', 'wc,wailing caverns', '', 'Deviate Faerie Dragon', 'faerie dragon', 'Rare: Arcane Explosion around itself and Sleep.', 'Keep it on you.', 'Dispel Sleep; heal the melee through Arcane Explosion.', 'Ranged are safer; melee watch their health.'),
(36, 1, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Rhahk''Zor', 'rhahkzor,rhak', 'Ogre foreman behind the first door: hits hard, nothing else.', 'Use your cooldowns if you''re low level, he slams hard.', 'Keep the tank topped, his hits are big.', 'Burn him.'),
(36, 2, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Miner Johnson', 'johnson', 'Rare miner: Rend on the tank, easy.', 'Plain tank and spank.', 'Heal the bleed.', 'Burn him.'),
(36, 3, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Sneed''s Shredder', 'shredder,sneeds shredder', 'Sneed in his shredder: Terrify fears, Distracting Pain. When the shredder breaks, Sneed jumps out: kill him too.', 'Hold the shredder, then grab Sneed when he pops out.', 'Heal through the fear.', 'Shredder first, then Sneed right away.'),
(36, 4, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Sneed', 'sneed', 'Jumps out of his broken shredder: Disarm, otherwise easy.', 'Pick him up as soon as he lands.', 'Light damage.', 'Burn him.'),
(36, 5, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Gilnid', 'gilnid,smelter', 'The smelter goblin: Molten Metal splashes fire, he comes with goblin crafters.', 'Pull the crafters with him and keep them on you.', 'Heal the splash damage.', 'Crafters first, then Gilnid.'),
(36, 6, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Mr. Smite', 'smite,mr smite', 'At two thirds and one third health he stuns everyone near (Smite Stomp), runs to his chest and switches weapons: two axes, then a big hammer.', 'Tank him near the chest so the weapon swap is quick; expect harder hits after each swap.', 'Top everyone before each stomp; the hammer phase hits the tank hard.', 'Ranged stay out of the stomp; burn him in the hammer phase.'),
(36, 7, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Captain Greenskin', 'greenskin', 'On the ship with his pirates: Cleave and Poisoned Harpoon.', 'Face him away from the group for the Cleave; pick up the pirates.', 'Cure the poison.', 'Pirates first if they''re loose, then the captain; stay behind him.'),
(36, 8, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Edwin VanCleef', 'vancleef,van cleef,edwin', 'Defias leader: Thrash gives him extra hits, and at half health he calls two Defias Blackguards.', 'Hold him and grab both Blackguards when they come.', 'Thrash spikes the tank; heal ahead of it.', 'Kill the Blackguards when they come, then VanCleef.'),
(36, 9, 'The Deadmines', 'deadmines,the deadmines,vc,van cleef', '', 'Cookie', 'cookie', 'The murloc cook in the ship: eats to heal himself, otherwise easy.', 'Plain tank and spank.', 'Light damage.', 'Burn him so his healing doesn''t matter.'),
(33, 1, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Rethilgore', 'rethilgore', 'The first worgen: Soul Drain on the tank. Easy.', 'Plain tank and spank.', 'Heal the drain.', 'Burn him and free the prisoners after.'),
(33, 2, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Razorclaw the Butcher', 'razorclaw,butcher', 'The kitchen worgen: hits hard and drains health. Easy with a good tank.', 'Face him away from the group.', 'Steady heals on the tank.', 'Burn him from behind.'),
(33, 3, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Baron Silverlaine', 'silverlaine', 'Veil of Shadow curses the tank (less healing) and he summons a worgen spirit.', 'Pick up the worgen spirit when it appears.', 'Mages and druids remove Veil of Shadow; heal through it otherwise.', 'Kill the worgen spirit, then the baron.'),
(33, 4, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Commander Springvale', 'springvale', 'Undead paladin with his servants: Holy Light on himself, Hammer of Justice stuns.', 'Hold him and his Haunted Servitors.', 'Expect a stun on the tank, heal ahead.', 'Interrupt every Holy Light.'),
(33, 5, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Odo the Blindwatcher', 'odo', 'Howling Rage makes him faster and stronger the lower he gets.', 'Use cooldowns near the end.', 'Damage on the tank rises as he drops: keep mana for the end.', 'Burn him fast.'),
(33, 6, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Deathsworn Captain', 'deathsworn', 'Rare: Cleave and Hamstring.', 'Face him away for the Cleave.', 'Steady heals.', 'Melee from behind.'),
(33, 7, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Fenrus the Devourer', 'fenrus', 'Big wolf: Toxic Saliva poisons the tank. After he dies Arugal sends voidwalkers down the hall.', 'Hold Fenrus; afterwards pull the voidwalkers one at a time.', 'Cure the poison on the tank.', 'Burn him, then the voidwalkers one by one.'),
(33, 8, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Wolf Master Nandos', 'nandos', 'Comes with his worgs and wolves.', 'Grab the wolves with him, an area threat helps.', 'Several mobs on the tank: steady heals.', 'Wolves first if they are loose, else Nandos.'),
(33, 9, 'Shadowfang Keep', 'sfk,shadowfang,shadowfang keep', '', 'Archmage Arugal', 'arugal', 'Teleports between the ledges, casts Void Bolt and curses one of us into a worgen that attacks the group. Thundershock hits the melee.', 'Chase him to each spot he ports to; the cursed worgen may need controlling.', 'Remove Arugal''s Curse quickly (mages and druids), heal the Void Bolts.', 'Interrupt Void Bolt, ranged keep hitting him wherever he blinks.'),
(48, 1, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Ghamoo-ra', 'ghamoora,turtle', 'Giant turtle: Trample, nothing else.', 'Plain tank and spank.', 'Light damage.', 'Burn it.'),
(48, 2, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Lady Sarevess', 'sarevess', 'Naga with two guards: Forked Lightning in front of her, Frost Nova and Slow.', 'Face her away from the group; grab her guards.', 'Dispel the Slow and Frost Nova, heal the lightning.', 'Stay out of her front; guards first if they''re loose.'),
(48, 3, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Gelihast', 'gelihast', 'Murloc boss: nets players in place and has murloc friends.', 'Hold him and the murlocs.', 'Dispel the net if you can.', 'Burn him.'),
(48, 4, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Lorgus Jett', 'lorgus', 'Twilight shaman: Lightning Bolt, Lightning Shield and Healing Wave.', 'Keep him in melee.', 'Heal the bolts.', 'Interrupt his Healing Wave; purge his shield.'),
(48, 5, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Baron Aquanis', 'aquanis', 'Called by the Fathom Stone: Frostbolts.', 'Plain tank and spank.', 'Heal the frostbolts.', 'Burn him.'),
(48, 6, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Twilight Lord Kelris', 'kelris', 'Mind Blast and Sleep. Clear his room''s cultists first.', 'Hold him in melee.', 'Dispel Sleep right away.', 'Interrupt his casts.'),
(48, 7, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Old Serra''kis', 'serrakis,shark', 'Big shark under water: Thrash. Watch your breath.', 'Hold it near an air pocket if you can.', 'Heal through Thrash, mind your breath.', 'Burn it and surface.'),
(48, 8, 'Blackfathom Deeps', 'bfd,blackfathom,blackfathom deeps', '', 'Aku''mai', 'akumai,hydra', 'Lighting the four braziers calls waves of turtles and murlocs; then Aku''mai. Poison Clouds and she goes frenzied at low health.', 'Tank her against the wall, keep her out of the clouds.', 'Save mana for the last third, she hits much harder then.', 'Step out of the green clouds; burn her in the frenzy.'),
(34, 1, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Targorr the Dread', 'targorr', 'Frenzies at low health.', 'Use a cooldown at the end.', 'Heal harder in his frenzy.', 'Burn him fast.'),
(34, 2, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Kam Deepfury', 'kam', 'Dwarf warrior: Shield Slam and Parry. Easy.', 'Plain tank and spank.', 'Light damage.', 'Hit him from behind.'),
(34, 3, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Hamhock', 'hamhock', 'Ogre shaman: Chain Lightning and Bloodlust.', 'Keep him on you.', 'Heal the chain lightning.', 'Ranged spread out, interrupt his casts.'),
(34, 4, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Bazil Thredd', 'bazil', 'Defias leader in the prison: Smoke Bomb stuns.', 'Hold him through the stuns.', 'Heal after the stuns.', 'Burn him.'),
(34, 5, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Dextren Ward', 'dextren', 'Mortal Strike and a fear.', 'Fear Ward or Berserker Rage help.', 'Mortal Strike cuts healing: heal ahead.', 'Burn him.'),
(34, 6, 'The Stockade', 'stocks,stockade,stockades,the stockade', '', 'Bruegal Ironknuckle', 'bruegal', 'Rare dwarf: hits hard.', 'Cooldowns if you''re low level.', 'Big hits on the tank.', 'Burn him.'),
(90, 1, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Grubbis', 'grubbis,chomper', 'Comes at the end of Emi Shortfuse''s trogg waves, with his pet Chomper.', 'Hold the trogg waves near Emi, then Grubbis and Chomper together.', 'Keep Emi alive through the waves as well as the tank.', 'Kill the troggs going for Emi; Chomper, then Grubbis.'),
(90, 2, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Viscous Fallout', 'viscous,fallout,ooze', 'Radioactive ooze: Toxic Volley poisons everyone near.', 'Plain tank and spank.', 'Cure poison and heal the volley.', 'Burn it; nature resistance helps.'),
(90, 3, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Electrocutioner 6000', 'electrocutioner', 'Chain Bolt jumps between players and Shock stuns. Drops the Workshop Key.', 'Keep it on you.', 'Heal the chain bolts.', 'Ranged spread out so the bolt doesn''t chain.'),
(90, 4, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Crowd Pummeler 9-60', 'pummeler,crowd pummeler', 'Crowd Pummel knocks back and stuns everyone in front of it; Arcing Smash cleaves.', 'Face it away from the group and put your back to a wall.', 'Stay behind it.', 'Everyone behind it, never in front.'),
(90, 5, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Dark Iron Ambassador', 'ambassador', 'Rare: Fire Shield and a fire elemental friend.', 'Hold both.', 'Light fire damage.', 'Elemental, then the ambassador.');
INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(90, 6, 'Gnomeregan', 'gnomer,gnomeregan', '', 'Mekgineer Thermaplugg', 'thermaplugg,mekgineer', 'Walking Bombs come out of the vents around the room and blow up in the group. Knock Away on the tank.', 'Back to a wall so Knock Away doesn''t throw you; get back fast.', 'Heal the bomb blasts, stay away from the vents.', 'Kill the bombs before they reach us (or press the vent buttons), then back on him.'),
(47, 1, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Roogug', 'roogug', 'Quilboar geomancer: Lightning Bolt and an earth totem.', 'Keep him in melee.', 'Heal the bolts.', 'Kill his totem, interrupt his bolts.'),
(47, 2, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Aggem Thorncurse', 'aggem', 'Heals himself and calls a boar spirit.', 'Pick up the boar spirit.', 'Steady heals.', 'Interrupt his heals, kill the boar, then him.'),
(47, 3, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Death Speaker Jargba', 'jargba', 'Mind controls one of us and casts Shadow Bolt.', 'Keep him on you; don''t hit the controlled friend hard.', 'Dispel the mind control if you can.', 'Burn him, the control ends when he dies.'),
(47, 4, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Overlord Ramtusk', 'ramtusk', 'Quilboar chief with guards and a Battle Shout.', 'Pull him with his guards and hold them all.', 'Several mobs on the tank.', 'Guards first, then Ramtusk.'),
(47, 5, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Agathelos the Raging', 'agathelos', 'Huge boar: Rampage knocks everyone near away, and he enrages.', 'Back to a wall, face him away.', 'Stay at range, heal through the enrage.', 'Ranged at range; melee from behind.'),
(47, 6, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Blind Hunter', 'blind hunter', 'Rare bat. Easy.', 'Plain tank and spank.', 'Light damage.', 'Burn it.'),
(47, 7, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Charlga Razorflank', 'charlga', 'The last boss: Chain Bolt, Renew and Purity heal her, she comes with two guards.', 'Hold her and the guards; pull her round a corner.', 'Heal the chain bolts.', 'Interrupt her heals; guards first, or crowd control them.'),
(47, 8, 'Razorfen Kraul', 'rfk,kraul,razorfen kraul', '', 'Earthcaller Halmgar', 'halmgar', 'Rare quilboar shaman with an earth elemental.', 'Hold both.', 'Light damage.', 'Burn him.'),
(189, 1, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Graveyard', 'Interrogator Vishas', 'vishas', 'Shadow Word: Pain on the tank. Easy.', 'Plain tank and spank.', 'Dispel the Shadow Word: Pain.', 'Burn him.'),
(189, 2, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Graveyard', 'Bloodmage Thalnos', 'thalnos,bloodmage', 'Flame Spike leaves fire on the ground, Fire Nova around him, Shadow Bolt.', 'Move him out of his Flame Spikes.', 'Step out of the fire, heal the nova.', 'Step out of the Flame Spike, interrupt his bolts.'),
(189, 3, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Graveyard', 'Azshir the Sleepless', 'azshir', 'Rare: a fear and a soul drain.', 'Fear Ward or Berserker Rage.', 'Heal through the fear.', 'Burn it.'),
(189, 4, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Graveyard', 'Fallen Champion', 'fallen champion', 'Rare undead warrior. Easy.', 'Plain tank and spank.', 'Light damage.', 'Burn it.'),
(189, 5, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Graveyard', 'Ironspine', 'ironspine', 'Rare: poisons the tank.', 'Plain tank and spank.', 'Cure the poison.', 'Burn it.'),
(189, 6, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Library', 'Houndmaster Loksey', 'loksey,houndmaster', 'Comes with three Scarlet Trackers (dogs) and Bloodlust.', 'Grab the three dogs with him.', 'Several mobs on the tank.', 'Dogs first, then Loksey.'),
(189, 7, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Library', 'Arcanist Doan', 'doan,arcanist', 'At half health he shields himself and then casts a big Arcane Explosion around him. Polymorph and Silence.', 'When the bubble goes up, run away from him with everyone, then pull him back.', 'Run away with the group when he bubbles; dispel polymorph.', 'Melee leave when he casts the explosion; interrupt his casts.'),
(189, 8, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Armory', 'Herod', 'herod', 'Whirlwind cuts everyone in melee, he enrages at low health. When he dies a wave of Scarlet Trainees runs in.', 'Stay on him through the Whirlwind; afterwards gather the trainees for area attacks.', 'Heal the tank hard during Whirlwind; be ready for the trainee wave.', 'Melee step away during Whirlwind; then area attacks on the trainees.'),
(189, 9, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Cathedral', 'Scarlet Commander Mograine', 'mograine,commander mograine', 'Paladin: Crusader Strike, Hammer of Justice, Lay on Hands. When he dies Whitemane comes, puts us to sleep and raises him.', 'Hold Mograine; when he is raised pick him up again.', 'Expect the Deep Sleep; heal the tank as soon as you wake.', 'Kill Mograine, then again after Whitemane raises him, then Whitemane.'),
(189, 10, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Cathedral', 'High Inquisitor Whitemane', 'whitemane', 'Deep Sleep on the whole group, then she resurrects Mograine. Heals and Power Word: Shield.', 'Hold both after the sleep.', 'Dispel her shield if you can.', 'Interrupt her heals and the resurrection; kill Mograine again, then her.'),
(189, 11, 'Scarlet Monastery', 'sm,scarlet monastery,monastery,sm gy,sm lib,sm arm,sm cath,graveyard,library,armory,cathedral', 'Cathedral', 'High Inquisitor Fairbanks', 'fairbanks', 'Hidden behind the cathedral: fear, curses and dispels.', 'Fear Ward or Berserker Rage.', 'Decurse, heal through the fear.', 'Burn him.'),
(129, 1, 'Razorfen Downs', 'rfd,downs,razorfen downs', '', 'Tuten''kash', 'tutenkash,spider', 'Called by the gong after spider waves: Web Spray stuns, a curse and Virulent Poison.', 'Hold the spiders near the gong, then Tuten''kash.', 'Cure poison and remove the curse.', 'Kill the spiders, then the big one.'),
(129, 2, 'Razorfen Downs', 'rfd,downs,razorfen downs', '', 'Mordresh Fire Eye', 'mordresh', 'Fire caster: Fireball and Fire Nova.', 'Keep him in melee.', 'Heal the nova on the melee.', 'Interrupt Fireball; melee watch the nova.'),
(129, 3, 'Razorfen Downs', 'rfd,downs,razorfen downs', '', 'Glutton', 'glutton', 'Disease Cloud around him, frenzies at low health.', 'Plain tank, cooldown at the end.', 'Cure disease; more healing in the frenzy.', 'Burn him.'),
(129, 4, 'Razorfen Downs', 'rfd,downs,razorfen downs', '', 'Ragglesnout', 'ragglesnout', 'Rare quilboar priest: Shadow Bolt and a mind control.', 'Keep him on you.', 'Dispel the control.', 'Interrupt and burn.'),
(129, 5, 'Razorfen Downs', 'rfd,downs,razorfen downs', '', 'Amnennar the Coldbringer', 'amnennar,coldbringer', 'Lich: Frost Nova on the melee, Frostbolt, and he calls Frozen Spectres partway through.', 'Pick up the spectres when they come.', 'Dispel Frost Nova on the tank, heal the frost damage.', 'Kill the spectres, then him; frost resistance helps.'),
(70, 1, 'Uldaman', 'ulda,uldaman', '', 'Revelosh', 'revelosh', 'Trogg shaman: Lightning Bolt and Chain Lightning.', 'Pull him round a corner into melee.', 'Heal the chain lightning.', 'Ranged spread; interrupt his bolts.'),
(70, 2, 'Uldaman', 'ulda,uldaman', '', 'Baelog', 'baelog,lost dwarves,eric,olaf', 'The Lost Dwarves: Baelog shoots, Eric "The Swift" runs fast and hits hard, Olaf blocks with his shield.', 'Grab all three; Eric moves fast, keep him on you.', 'Three on the tank at first: steady heals.', 'Eric first, then Baelog, Olaf last.'),
(70, 3, 'Uldaman', 'ulda,uldaman', '', 'Ironaya', 'ironaya', 'Stone keeper: Arcing Smash cleaves, Knock Away throws the tank, War Stomp at half health.', 'Face her away from everyone, back to a wall.', 'Stay at range, heal through the knockbacks.', 'Melee from behind; step out before the stomp.'),
(70, 4, 'Uldaman', 'ulda,uldaman', '', 'Obsidian Sentinel', 'obsidian sentinel,sentinel', 'Breaks off Obsidian Shards as it takes damage.', 'Gather the shards on you.', 'Several mobs on the tank as shards pile up.', 'Area attacks on the shards, then the sentinel.'),
(70, 5, 'Uldaman', 'ulda,uldaman', '', 'Ancient Stone Keeper', 'stone keeper', 'Sand storms wander the room and Trample hits the melee.', 'Move it away from the sand storms.', 'Dodge the storms, heal the trample.', 'Stay out of the storms.'),
(70, 6, 'Uldaman', 'ulda,uldaman', '', 'Galgann Firehammer', 'galgann', 'Dark Iron caster: Fire Nova, Flame Lash and Amplify Flames.', 'Hold him in melee.', 'Heal the fire on the melee.', 'Melee step out on Fire Nova; interrupt his casts.'),
(70, 7, 'Uldaman', 'ulda,uldaman', '', 'Grimlok', 'grimlok', 'Trogg chief: Lightning Bolt, Shrink and Bloodlust.', 'Keep him in melee.', 'Heal the bolts.', 'Interrupt his bolts.'),
(70, 8, 'Uldaman', 'ulda,uldaman', '', 'Archaedas', 'archaedas', 'Wakes when the disc is used: Ground Tremor stuns, he awakens Earthen Guardians and later the Vault Warders.', 'Grab the guardians as they wake and hold Archaedas.', 'Heal through the tremors; several adds on the tank.', 'Kill the guardians quickly, then focus Archaedas.'),
(209, 1, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Antu''sul', 'antusul', 'Basilisk master on the hill: calls basilisks, drops a Healing Ward and an Earthgrab totem.', 'Grab the basilisks as they come.', 'Several mobs on the tank.', 'Kill the Healing Ward at once, area attacks on the basilisks, then him.'),
(209, 2, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Theka the Martyr', 'theka', 'Turns into a scarab near the end and becomes immune to physical damage; Fevered Plague.', 'Keep threat with spells or hold on until the casters finish him.', 'Cure the plague.', 'Casters finish him in scarab form; melee switch to wands or wait.'),
(209, 3, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Witch Doctor Zum''rah', 'zumrah,witch doctor', 'In the graveyard: raises zombies from the graves, Shadow Bolt Volley, and a Ward of Zum''rah.', 'Pull him away from the graves, pick up the zombies.', 'Heal the volley.', 'Kill his ward, then him.'),
(209, 4, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Sergeant Bly', 'bly,pyramid,stairs', 'Free Bly''s crew, then waves of trolls climb the pyramid stairs. After that the crew turns on us.', 'Hold the top of the stairs; then pick up Bly''s crew.', 'Long fight: watch mana on the stairs.', 'Area attacks on the stair waves; Murta the healer first in the crew fight.'),
(209, 5, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Shadowpriest Sezz''ziz', 'sezzziz', 'Comes down after the pyramid waves with Nekrum: heals, Psychic Scream.', 'Hold Nekrum and Sezz''ziz together.', 'Fear Ward on the tank.', 'Sezz''ziz first (he heals), then Nekrum.'),
(209, 6, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Nekrum Gutchewer', 'nekrum', 'Big zombie with Sezz''ziz: hits hard.', 'Hold him while the others kill the priest.', 'Steady heals on the tank.', 'Sezz''ziz first, then Nekrum.'),
(209, 7, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Hydromancer Velratha', 'velratha,hydromancer', 'Naga at the pool: Healing Wave and frost spells. Her death is needed for the mallet.', 'Keep her in melee.', 'Heal the frost damage.', 'Interrupt her Healing Wave.'),
(209, 8, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Gahz''rilla', 'gahzrilla', 'Called with the Mallet of Zul''Farrak: Freeze Solid freezes a player, Gahz''rilla Slam knocks up, Icicles.', 'Plain tank, he hits hard.', 'Heal through the slams; keep the frozen alive.', 'Ranged spread; burn him.'),
(209, 9, 'Zul''Farrak', 'zf,zulfarrak,zul farrak', '', 'Chief Ukorz Sandscalp', 'ukorz,sandscalp,ruuzlu', 'With Ruuzlu: Wide Slash cleaves and he enrages.', 'Face Ukorz away from the group; pick up Ruuzlu too.', 'Heal through the enrage.', 'Stay behind Ukorz; kill Ruuzlu first.'),
(349, 1, 'Maraudon', 'mara,maraudon', '', 'Noxxion', 'noxxion', 'Toxic Volley poisons everyone and Uppercut; now and then he splits into small Spawns and can''t be hurt until they die.', 'Gather the Spawns when he splits.', 'Cure poison, heal the volley.', 'Area attacks on the Spawns, then him.'),
(349, 2, 'Maraudon', 'mara,maraudon', '', 'Razorlash', 'razorlash', 'Plant beast: Cleave and Puncture.', 'Face him away.', 'Steady heals.', 'From behind.'),
(349, 3, 'Maraudon', 'mara,maraudon', '', 'Lord Vyletongue', 'vyletongue', 'Satyr lord with his guards: blinks around and fires Multi-Shot.', 'Grab his guards; chase him when he blinks.', 'Heal the multi-shot.', 'Guards first, then him.'),
(349, 4, 'Maraudon', 'mara,maraudon', '', 'Celebras the Cursed', 'celebras', 'Wrath, Entangling Roots, and he summons treants.', 'Pick up the treants.', 'Dispel the roots.', 'Kill the treants, interrupt his Wrath.'),
(349, 5, 'Maraudon', 'mara,maraudon', '', 'Landslide', 'landslide', 'Giant rock elemental: Knock Away and Trample, calls small rock adds.', 'Back to a wall, grab the adds.', 'Stay at range.', 'Adds first if loose, else Landslide.'),
(349, 6, 'Maraudon', 'mara,maraudon', '', 'Tinkerer Gizlock', 'gizlock', 'Goblin engineer: a dragon gun burns everyone in front, and bombs.', 'Face him away from the group.', 'Stay behind him.', 'Spread out, stay out of his front.'),
(349, 7, 'Maraudon', 'mara,maraudon', '', 'Rotgrip', 'rotgrip', 'Huge crocolisk in the water: Puncture and Fatal Bite.', 'Plain tank, he hits hard.', 'Big hits on the tank.', 'Burn him.'),
(349, 8, 'Maraudon', 'mara,maraudon', '', 'Princess Theradras', 'theradras,princess', 'Dust Field hurts everyone near her, she throws Boulders at range and Repulsive Gaze knocks back.', 'Hold her, step back out of the Dust Field and pull her with you.', 'Stay spread at range.', 'Melee step out of the Dust Field; ranged spread for Boulder.');
INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(109, 1, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Atal''alarion', 'atalalarion,statue boss', 'Raised by touching the statues in the pit in the right order: Sweeping Slam and Knock Away.', 'Face him away, back to a wall.', 'Heal through the slams.', 'From behind.'),
(109, 2, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Jammal''an the Prophet', 'jammalan,prophet', 'With Ogom the Wretched: Hex of Jammal''an turns a player against us, Healing Wave, totems.', 'Hold both trolls.', 'Dispel or crowd control the hexed player.', 'Interrupt his Healing Wave; kill Jammal''an, then Ogom.'),
(109, 3, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Ogom the Wretched', 'ogom', 'Jammal''an''s shadow caster: Shadow Bolt and Curse of Weakness.', 'Hold him with Jammal''an.', 'Decurse.', 'After Jammal''an.'),
(109, 4, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Dreamscythe', 'dreamscythe', 'Green dragonkin on the balcony: Acid Breath in front and Wing Flap.', 'Face it away from the group.', 'Stay out of its front.', 'From the sides or behind.'),
(109, 5, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Weaver', 'weaver', 'Green dragonkin: Acid Breath in front and Wing Flap.', 'Face it away from the group.', 'Stay out of its front.', 'From the sides or behind.'),
(109, 6, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Morphaz', 'morphaz', 'Dragonkin: Acid Breath in front and Thrash.', 'Face it away.', 'Out of its front.', 'Behind it.'),
(109, 7, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Hazzas', 'hazzas', 'Dragonkin: Acid Breath in front.', 'Face it away.', 'Out of its front.', 'Behind it.'),
(109, 8, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Avatar of Hakkar', 'avatar,hakkar avatar', 'Event: kill the Hakkari Bloodkeepers and use their blood to put out the Eternal Flames, then the Avatar comes: Cause Insanity, Curse of Tongues, Lash.', 'Face him away; crowd control a player he drives insane.', 'Decurse Curse of Tongues.', 'Bloodkeepers first in the event, then the Avatar.'),
(109, 9, 'Sunken Temple', 'st,sunken temple,temple of atalhakkar,atal hakkar', '', 'Shade of Eranikus', 'eranikus,shade', 'Green dragon: Acid Breath in front, War Stomp, and Deep Slumber puts people to sleep.', 'Face him away from the group.', 'Dispel the sleep; nature resistance helps.', 'Never in front of him.'),
(230, 1, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Lord Roccor', 'roccor', 'Fire and earth shocks and Ground Tremor stuns. Easy.', 'Plain tank and spank.', 'Heal after the stuns.', 'Burn him.'),
(230, 2, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'High Interrogator Gerstahn', 'gerstahn,interrogator', 'Shadow priest: Shadow Word: Pain, Psychic Scream fears, Mana Burn.', 'Fear Ward or Tremor Totem on you.', 'Dispel Shadow Word: Pain; stay out of her scream range.', 'Interrupt and burn her.'),
(230, 3, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Houndmaster Grebmar', 'grebmar', 'Bloodlust and Demoralizing Shout, with his hounds around.', 'Grab the hounds with him.', 'Steady heals.', 'Hounds if loose, then Grebmar.'),
(230, 4, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Gorosh the Dervish', 'gorosh', 'Ring of Law: Whirlwind cuts the melee.', 'Hold him; the Ring''s adds come with him.', 'Heal the whirlwind.', 'Melee step out of Whirlwind.'),
(230, 5, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Grizzle', 'grizzle', 'Ring of Law: Thunderclap and Ground Tremor stun.', 'Hold him.', 'Heal after the stuns.', 'Burn him.'),
(230, 6, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Eviscerator', 'eviscerator', 'Ring of Law: Shadow Bolt Volley, and a shield that stops spells.', 'Hold him.', 'Heal the volleys.', 'Melee do the work while his spell shield is up.'),
(230, 7, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Hedrum the Creeper', 'hedrum', 'Ring of Law spider: Paralyzing Poison and webs.', 'Hold him.', 'Cure the poison.', 'Burn him.'),
(230, 8, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Ok''thor the Breaker', 'okthor', 'Ring of Law caster: Arcane Bolt, Arcane Explosion, Polymorph.', 'Hold him in melee.', 'Dispel the polymorph.', 'Interrupt his bolts; melee watch the explosion.'),
(230, 9, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Anub''shiah', 'anubshiah', 'Ring of Law: Shadow Bolt, curses and Enveloping Web.', 'Hold him.', 'Decurse.', 'Interrupt his bolts.'),
(230, 10, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Pyromancer Loregrain', 'loregrain', 'Molten Blast and a Searing Totem.', 'Keep him in melee.', 'Heal the fire damage.', 'Kill the totem, interrupt his blasts.'),
(230, 11, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Lord Incendius', 'incendius', 'At the Black Anvil: Fire Storm, Fiery Burst, Mighty Blow knocks back, and a curse on everyone.', 'Back to a wall for the knockbacks.', 'Decurse; fire resistance helps.', 'Burn him.'),
(230, 12, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Warder Stilgiss', 'stilgiss,verek', 'Frost caster with Verek his hound: Frost Nova, Frost Ward. Verek enrages when Stilgiss dies.', 'Hold both.', 'Dispel the nova on the tank.', 'Stilgiss first, then Verek.'),
(230, 13, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Fineous Darkvire', 'fineous', 'Dark Iron paladin: Holy Strike and Holy Light.', 'Plain tank and spank.', 'Steady heals.', 'Interrupt Holy Light.'),
(230, 14, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Bael''Gar', 'baelgar', 'Giant fire elemental: calls lava spawns that split if left alone.', 'Hold him and grab the spawns.', 'Fire resistance helps.', 'Kill the spawns quickly, then him.'),
(230, 15, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'General Angerforge', 'angerforge', 'Cleave, Flurry and Sunder; at low health he calls Anvilrage reservists and medics.', 'Face him away; grab the reinforcements.', 'Several on the tank at the end.', 'Medics first, then the reservists or Angerforge.'),
(230, 16, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Golem Lord Argelmach', 'argelmach,golem lord', 'Chain Lightning and Shock; he wakes the golems around his room.', 'Clear or grab the golems; hold Argelmach.', 'Heal the chain lightning.', 'Ranged spread; interrupt his chain lightning.'),
(230, 17, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Hurley Blackbreath', 'hurley', 'Comes for his stolen ale in the Grim Guzzler: Drunken Rage and fire breath.', 'Face him away.', 'Steady heals.', 'Burn him.'),
(230, 18, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Phalanx', 'phalanx', 'Golem guard of the Grim Guzzler: Fireball Volley, Mighty Blow knocks back, Thunderclap.', 'Back to a wall.', 'Heal the volley.', 'Burn him.'),
(230, 19, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Ribbly Screwspigot', 'ribbly', 'Goblin with his friends in the Grim Guzzler. Easy.', 'Hold them all.', 'Light damage.', 'Burn them.'),
(230, 20, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Plugger Spazzring', 'plugger', 'The barkeep: attacks if you steal the ale. Easy.', 'Plain tank and spank.', 'Light damage.', 'Burn him.'),
(230, 21, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Ambassador Flamelash', 'flamelash', 'Burning Spirits walk from the runes around the room into him and make him stronger.', 'Hold him in the middle.', 'Heal more if spirits reach him.', 'Kill the spirits before they reach him, then back on him.'),
(230, 22, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Doom''rel', 'doomrel,the seven,seven dwarves,the seven dwarves', 'The Seven: talk to Doom''rel and the seven dwarves come one at a time, Doom''rel last.', 'Hold each one as it comes; keep them apart.', 'A long fight: pace your mana.', 'Kill each as it comes; interrupt Vile''rel''s heals and Haterel''s shadow.'),
(230, 23, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Anger''rel', 'angerrel', 'One of the Seven: a warrior with Sunder and Shield Block.', 'Plain tank.', 'Steady heals.', 'Burn him.'),
(230, 24, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Magmus', 'magmus', 'Giant golem at the throne room doors: Fiery Burst and War Stomp; the fire jets along the hall stop once he''s dead.', 'Hold him away from the jets.', 'Heal through the burst.', 'Burn him.'),
(230, 25, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Emperor Dagran Thaurissan', 'emperor,thaurissan,dagran,moira', 'Princess Moira heals him: interrupt or crowd control her (don''t kill her if someone needs her alive for a quest). Hand of Thaurissan stuns, Avatar of Flame burns all around him.', 'Hold the emperor facing away; heal-interrupts are on the others.', 'Heal through Avatar of Flame.', 'Interrupt Moira''s heals and burn the emperor.'),
(230, 26, 'Blackrock Depths', 'brd,blackrock depths,depths', '', 'Panzor the Invincible', 'panzor', 'Rare golem: hits hard.', 'Plain tank.', 'Big hits.', 'Burn it.'),
(229, 1, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Highlord Omokk', 'omokk', 'Big ogre with ogre guards: Cleave and Knock Away.', 'Face him away and grab his guards.', 'Several mobs on the tank.', 'Guards first, then Omokk.'),
(229, 2, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Shadow Hunter Vosh''gajin', 'voshgajin,vosh', 'Troll witch doctor: Hex, Curse of Blood and Cleave.', 'Face her away.', 'Dispel the hex and the curse.', 'Burn her.'),
(229, 3, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'War Master Voone', 'voone', 'Throws axes, Mortal Strike, Cleave, Snap Kick.', 'Face him away; Mortal Strike cuts your healing.', 'Heal ahead of the mortal strikes.', 'From behind.'),
(229, 4, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Mother Smolderweb', 'smolderweb,mother', 'Spider queen: Crystallize stuns, poison bites.', 'Plain tank.', 'Cure the poison.', 'Burn her.'),
(229, 5, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Urok Doomhowl', 'urok', 'Called with Omokk''s head on the pike: ogre waves first, then Urok.', 'Hold the ogres as they come, then Urok.', 'Long fight: pace your mana.', 'Kill the waves, then Urok.'),
(229, 6, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Quartermaster Zigris', 'zigris', 'Shoots, nets and drinks healing potions.', 'Keep him in melee.', 'Light damage.', 'Burn him through his potions.'),
(229, 7, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Halycon', 'halycon', 'Big worg: Rend and Thrash. When she dies, Gizrul comes running.', 'Stay ready to pick up Gizrul.', 'Keep mana for Gizrul.', 'Burn her, then Gizrul.'),
(229, 8, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Gizrul the Slavener', 'gizrul', 'Comes after Halycon: Fatal Bite and Frenzy.', 'Use a cooldown in his frenzy.', 'Heavy damage on the tank in the frenzy.', 'Hunters Tranquilizing Shot the frenzy.'),
(229, 9, 'Blackrock Spire', 'lbrs,ubrs,blackrock spire,lower blackrock spire,upper blackrock spire,spire', 'Lower', 'Overlord Wyrmthalak', 'wyrmthalak', 'Cleave, Demoralizing Shout; at half health he calls two Bloodaxe Veterans.', 'Face him away; grab the veterans.', 'Three on the tank at the end.', 'Veterans or crowd control them, then Wyrmthalak.'),
(229, 101, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'Pyroguard Emberseer', 'emberseer,pyroguard', 'Kill the Blackhand Incarcerators around the room, then free him at the altar: Fire Nova, Fireball Volley, Flame Buffet.', 'Hold him in the middle.', 'Heavy fire damage on everyone: fire resistance helps.', 'Burn him fast.'),
(229, 102, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'Solakar Flamewreath', 'solakar,rookery', 'The rookery: waves of whelps and handlers, then Solakar. Don''t break the eggs.', 'Hold the handlers and whelps in a corner.', 'Long fight, pace your mana.', 'Handlers first, area attacks on the whelps.'),
(229, 103, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'Jed Runewatcher', 'jed', 'Rare guard. Easy.', 'Plain tank.', 'Light damage.', 'Burn him.'),
(229, 104, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'Goraluk Anvilcrack', 'goraluk', 'The blacksmith: Cleave and Backhand.', 'Face him away.', 'Steady heals.', 'From behind.'),
(229, 105, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'Warchief Rend Blackhand', 'rend,gyth', 'Waves of orcs and dragonkin pour out of the arena gates, then Rend rides in on Gyth (breaths); when Gyth dies Rend fights on foot: Whirlwind and Cleave.', 'Hold the waves in the corner by the entrance; face Gyth away from the group.', 'Long fight: drink between waves.', 'Kill the waves fast; never stand in front of Gyth; step out of Rend''s Whirlwind.'),
(229, 106, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'The Beast', 'the beast,beast', 'Fireballs, Flamebreak around him, a roar that fears, and he pulls players to him.', 'Fear Ward on you; face him away.', 'Stand behind him at range.', 'Stand behind him.');
INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(229, 107, 'Blackrock Spire', 'ubrs,upper blackrock spire', 'Upper', 'General Drakkisath', 'drakkisath,drakk', 'Two Chromatic Elite Guards: separate them. Drakkisath: Flamestrike, Cleave, Conflagration disorients his tank.', 'Main tank on Drakkisath facing away; off-tank the guards, then take over during Conflagration.', 'Heal both tanks; fire resistance helps.', 'Guards first, then Drakkisath; step out of Flamestrike.'),
(429, 1, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'East', 'Pusillin', 'pusillin,imp', 'The imp runs off when you talk to him; chase him through the wing. At the end he fights with imp friends: Fireball, Blast Wave.', 'Grab his imps at the end.', 'Heal the blast wave.', 'Imps, then Pusillin.'),
(429, 2, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'East', 'Zevrim Thornhoof', 'zevrim', 'Sacrifice pins a player and drains them, Intense Pain hurts the tank.', 'Plain tank, heavy hits.', 'Heal the sacrificed player hard.', 'Burn him quickly.'),
(429, 3, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'East', 'Hydrospawn', 'hydrospawn', 'Water elemental: Riptide, Submersion, and he splits into Hydrolings at low health.', 'Grab the Hydrolings.', 'Several on the tank at the end.', 'Area attacks on the Hydrolings.'),
(429, 4, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'East', 'Lethtendris', 'lethtendris,pimgib', 'With her imp Pimgib: Shadow Bolt Volley, Enfeeble, Void Bolt.', 'Hold both.', 'Heal the volley.', 'Interrupt her bolts; Pimgib first.'),
(429, 5, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'East', 'Alzzin the Wildshaper', 'alzzin,wildshaper', 'Changes form as he loses health and hits harder in his beast forms; Wither and Enervate weaken the group.', 'Keep him in the open, cooldowns for his beast forms.', 'Dispel what you can; heavy tank damage late.', 'Burn him.'),
(429, 6, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'West', 'Tendris Warpwood', 'tendris,warpwood', 'Huge treant: Entangle roots everyone, Grasping Vines and Trample. His Ironbark Protectors are nearby.', 'Hold him away from the protectors.', 'Dispel the roots, heal the trample.', 'Burn him.'),
(429, 7, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'West', 'Illyanna Ravenoak', 'illyanna,ferra', 'Hunter with her bear Ferra: Volley, Immolation Trap, Concussive Shot.', 'Grab Ferra and Illyanna.', 'Heal the volley.', 'Ferra first or crowd control it; spread for the volley.'),
(429, 8, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'West', 'Magister Kalendris', 'kalendris', 'Shadow priest: Mind Blast, Shadow Word: Pain, and Dominate Mind on a player.', 'Hold him; don''t hit the controlled player.', 'Dispel the mind control and the Shadow Word: Pain.', 'Interrupt his Mind Blast.'),
(429, 9, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'West', 'Immol''thar', 'immolthar', 'Freed by destroying the five pylons. Trample, Infected Bite, Eyes of Immol''thar come out, and Portal of Immol''thar sends a player away.', 'Face him away; he hits hard.', 'Cure the disease; heal whoever he portals.', 'Kill the Eyes, then him.'),
(429, 10, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'West', 'Prince Tortheldrin', 'tortheldrin,prince', 'Whirlwind cuts the melee; Arcane Blast, Counterspell, and he pulls a player to him.', 'Hold him through the Whirlwind.', 'Heal the whirlwind.', 'Melee step out of Whirlwind; casters watch the counterspell.'),
(429, 11, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Guard Mol''dar', 'moldar', 'Gordok guard. Kill him for loot or leave him alive for the tribute.', 'Plain tank.', 'Light damage.', 'Burn him.'),
(429, 12, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Stomper Kreeg', 'kreeg,stomper', 'Drunk ogre: War Stomp and Whirlwind. Leave him alive for the tribute, or kill him.', 'Plain tank.', 'Heal through the stomps.', 'Melee step out of Whirlwind.'),
(429, 13, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Guard Fengus', 'fengus', 'Gordok guard. Kill him or leave him for the tribute.', 'Plain tank.', 'Light damage.', 'Burn him.'),
(429, 14, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Guard Slip''kik', 'slipkik', 'Gordok guard. A Freezing Trap trick gets you past him for the tribute.', 'Plain tank.', 'Light damage.', 'Burn him.'),
(429, 15, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Captain Kromcrush', 'kromcrush', 'Intimidating Shout fears and Mortal Strike; he calls Gordok Reavers.', 'Fear Ward or Tremor; grab the reavers.', 'Heal ahead of the mortal strikes.', 'Reavers, then Kromcrush.'),
(429, 16, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'Cho''Rush the Observer', 'chorush', 'King Gordok''s ogre mage: heals Gordok and casts Mind Blast.', 'Hold him with Gordok.', 'Heal through the casts.', 'Kill or interrupt Cho''Rush first.'),
(429, 17, 'Dire Maul', 'dire maul,dm east,dm west,dm north,dme,dmw,dmn,tribute', 'North', 'King Gordok', 'gordok,king gordok', 'Kill Cho''Rush first. Gordok: Mortal Strike, War Stomp, Berserker Charge.', 'Face Gordok away from the group.', 'Heal ahead of the mortal strikes.', 'Cho''Rush first, then Gordok from behind.'),
(289, 1, 'Scholomance', 'scholo,scholomance', '', 'Kirtonos the Herald', 'kirtonos', 'Called with the Blood of Innocents at the balcony brazier. Bat form: swoops, Disarm, Wing Flap. Humanoid form: Curse of Tongues, Shadow Bolt Volley, Dominate Mind.', 'Hold him and pick him back up after each form change.', 'Decurse, dispel the mind control, heal the volley.', 'Burn him; casters decurse between casts.'),
(289, 2, 'Scholomance', 'scholo,scholomance', '', 'Jandice Barov', 'jandice', 'Splits into many illusions: the real Jandice is the one that takes damage. Curse of Blood.', 'Grab the illusions with area threat.', 'Decurse.', 'Find the real one and burn her; area attacks clear the illusions.'),
(289, 3, 'Scholomance', 'scholo,scholomance', '', 'Rattlegore', 'rattlegore', 'Huge bone golem: War Stomp and Knock Away.', 'Back to a wall.', 'Heal after the stomps.', 'Burn him.'),
(289, 4, 'Scholomance', 'scholo,scholomance', '', 'Marduk Blackpool', 'marduk', 'Viewing room event with Vectus: Shadow Bolt Volley and Cleave; students come in waves first.', 'Hold the students, then Marduk.', 'Heal the volley.', 'Students, then the two bosses.'),
(289, 5, 'Scholomance', 'scholo,scholomance', '', 'Vectus', 'vectus', 'Viewing room event: Fire Nova and Flamestrike.', 'Hold him away from the group.', 'Step out of Flamestrike.', 'Melee watch the nova.'),
(289, 6, 'Scholomance', 'scholo,scholomance', '', 'Ras Frostwhisper', 'ras,frostwhisper', 'Lich: Frostbolt, Frost Nova, Chill Nova, Knock Away. Fire works well on him.', 'Back to a wall.', 'Dispel the frostbolt slows.', 'Fire damage; interrupt Frostbolt.'),
(289, 7, 'Scholomance', 'scholo,scholomance', '', 'Instructor Malicia', 'malicia', 'Heal, Renew and Corruption; she calls the dead.', 'Grab what she calls.', 'Dispel the corruption.', 'Interrupt her heals.'),
(289, 8, 'Scholomance', 'scholo,scholomance', '', 'Doctor Theolen Krastinov', 'krastinov,theolen,the butcher', 'The Butcher: hits hard with Rend and Frenzy.', 'Cooldowns in his frenzy.', 'Heavy tank damage.', 'Hunters Tranquilizing Shot the frenzy; burn him.'),
(289, 9, 'Scholomance', 'scholo,scholomance', '', 'Lorekeeper Polkelt', 'polkelt', 'Corrosive Acid and Noxious Catalyst, a disease that bursts on the people around.', 'Plain tank.', 'Cure disease right away.', 'Spread out.'),
(289, 10, 'Scholomance', 'scholo,scholomance', '', 'The Ravenian', 'ravenian', 'Trample, Cleave and Sunder Armor.', 'Face it away from the group.', 'Steady heals.', 'Melee from behind.'),
(289, 11, 'Scholomance', 'scholo,scholomance', '', 'Lord Alexei Barov', 'alexei', 'Unholy Aura burns everyone around him; Corruption.', 'Plain tank.', 'Shadow damage on everyone near.', 'Burn him.'),
(289, 12, 'Scholomance', 'scholo,scholomance', '', 'Lady Illucia Barov', 'illucia', 'Shadow Shock, a fear and Curse of Agony.', 'Fear Ward or Tremor.', 'Decurse.', 'Burn her.'),
(289, 13, 'Scholomance', 'scholo,scholomance', '', 'Darkmaster Gandling', 'gandling,darkmaster', 'Shadow Portal sends a player into one of the side rooms full of undead, the door locks until they die. Arcane Missiles and a curse.', 'Hold him; if you''re ported, tank the room''s undead and come back.', 'Decurse; whoever is ported needs heals, go to the door.', 'Burn him; help a ported friend clear the room.'),
(329, 1, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Timmy the Cruel', 'timmy', 'Appears in the market square once its undead are cleared: Ravenous Claw and he enrages.', 'Plain tank, cooldowns at the end.', 'Heavy hits on the tank.', 'Burn him.'),
(329, 2, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Cannon Master Willey', 'willey', 'Calls Crimson Riflemen while he fights; Knock Away and Shoot.', 'Back to a wall, grab the riflemen.', 'Heal the riflemen''s shots.', 'Riflemen if they spread out, else Willey.'),
(329, 3, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Archivist Galford', 'galford', 'Fire Nova, Burning Winds and Pyroblast in the library.', 'Hold him in melee.', 'Heal the fire damage.', 'Interrupt Pyroblast.'),
(329, 4, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Grand Crusader Dathrohan', 'dathrohan,balnazzar,balnazar', 'Paladin who turns into the demon Balnazzar at half health: Shadow Shock, Psychic Scream, Sleep and Mind Control.', 'Fear Ward or Tremor on you; pick him back up after the change.', 'Dispel the sleep; crowd control or dispel the mind controlled.', 'Burn him; don''t kill a controlled friend.'),
(329, 5, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Malor the Zealous', 'malor', 'Guards the medallion in the Scarlet bastion. Holy spells and heals.', 'Plain tank.', 'Steady heals.', 'Interrupt his heals.'),
(329, 6, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Hearthsinger Forresten', 'forresten,hearthsinger', 'Rare bard: Disarm and Enchanting Lullaby.', 'Plain tank.', 'Dispel the lullaby.', 'Burn him.'),
(329, 7, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'Skul', 'skul', 'Rare caster: Frostbolt and Arcane Bolt.', 'Hold him in melee.', 'Light damage.', 'Interrupt and burn.'),
(329, 8, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Live side', 'The Unforgiven', 'unforgiven', 'Spawns with Vengeful Phantoms: Frost Nova and Mind Numbing poison.', 'Grab the phantoms.', 'Dispel the nova on the tank.', 'Phantoms, then him.'),
(329, 9, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Baroness Anastari', 'anastari,baroness', 'Banshee: Possess takes over a player, Banshee Wail and Banshee Curse.', 'Hold her; she ends Possess when she is hurt enough.', 'Decurse; heal the possessed when it ends.', 'Burn her, don''t hurt the possessed friend.'),
(329, 10, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Nerub''enkan', 'nerubenkan', 'Crypt Scarabs swarm out, Encasing Webs root, Pierce Armor.', 'Grab the scarabs.', 'Dispel the webs and the poison.', 'Area attacks on the scarabs, then him.'),
(329, 11, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Maleki the Pallid', 'maleki', 'Frostbolt, Drain Life and Ice Tomb on a player.', 'Hold him in melee.', 'Heal the frozen player.', 'Interrupt Frostbolt and Drain Life.'),
(329, 12, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Magistrate Barthilas', 'barthilas,magistrate', 'Draining Blow, Crowd Pummel knocks back the melee, Mighty Blow.', 'Face him away, back to a wall.', 'Heal after the pummels.', 'From behind; the baron run timer starts at him.'),
(329, 13, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Ramstein the Gorger', 'ramstein', 'Abomination at the slaughterhouse: Trample and Knockout stun the tank. Black Guards come out after he dies.', 'Get your threat back after the knockouts; grab the Black Guards after.', 'Heal through the stuns.', 'Watch threat while the tank is stunned; then the guards.'),
(329, 14, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Baron Rivendare', 'baron,rivendare', 'Raises skeletons and eats them with Death Pact to heal; Unholy Aura burns everyone near, Mortal Strike, Cleave.', 'Face him away, grab the skeletons.', 'Shadow damage on everyone: shadow resistance helps.', 'Kill the skeletons quickly so he can''t heal, then him.'),
(329, 15, 'Stratholme', 'strat,stratholme,strat live,strat ud,strat undead,baron run', 'Undead side', 'Stonespine', 'stonespine', 'Rare gargoyle: hits hard.', 'Plain tank.', 'Steady heals.', 'Burn it.'),
(409, 1, 'Molten Core', 'mc,molten core', '', 'Lucifron', 'lucifron', 'Two Flamewaker Protectors with him mind control people: kill them first. Lucifron casts Impending Doom and Lucifron''s Curse on the raid.', 'One tank on each Protector, one on Lucifron facing away (Shadow Shock).', 'Priests and paladins dispel Impending Doom; mages and druids remove the curse; free the mind controlled.', 'Protectors first, then Lucifron.'),
(409, 2, 'Molten Core', 'mc,molten core', '', 'Magmadar', 'magmadar,dog', 'Panic fears everyone near him about every 30 seconds, Lava Bombs leave fire under players, and he goes into Frenzy.', 'Fear Ward and Tremor Totem on you; tank him at the back so the raid sees his side.', 'Stay out of fear range if you can; heal the tank hard through Frenzy.', 'Hunters Tranquilizing Shot the Frenzy. Step out of Lava Bombs.'),
(409, 3, 'Molten Core', 'mc,molten core', '', 'Gehennas', 'gehennas', 'Two Flamewakers with him. Gehennas'' Curse cuts healing by 75%, Rain of Fire on the raid, Shadow Bolt.', 'Off-tanks take the Flamewakers (their Fist of Ragnaros stuns); main tank on Gehennas.', 'Decurse right away.', 'Flamewakers first, then Gehennas. Move out of Rain of Fire.'),
(409, 4, 'Molten Core', 'mc,molten core', '', 'Garr', 'garr,firesworn', 'Eight Firesworn: each one dying explodes and makes Garr stronger. Banish some, off-tank the rest, kill them one at a time away from the raid, then Garr.', 'Main tank on Garr; off-tanks hold one Firesworn each.', 'Anti-magic pulses strip buffs; heal the off-tanks.', 'Kill the Firesworn one by one where the tank calls, step back when one is low.');
INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(409, 5, 'Molten Core', 'mc,molten core', '', 'Shazzrah', 'shazzrah', 'Blinks to a random player and casts Arcane Explosion around himself. Shazzrah''s Curse doubles magic damage; Deaden Magic on himself.', 'Run to him after every blink; threat resets.', 'Ranged stand apart; decurse.', 'Purge or dispel Deaden Magic; ranged spread out.'),
(409, 6, 'Molten Core', 'mc,molten core', '', 'Baron Geddon', 'geddon', 'Living Bomb: that player runs away from everyone before it blows. Inferno burns everyone near him. Ignite Mana drains mana: dispel it.', 'Run out during Inferno, come back after.', 'Dispel Ignite Mana; heal the bomb carrier.', 'Run out with a bomb, out of Inferno; at the very end he explodes, move away.'),
(409, 7, 'Molten Core', 'mc,molten core', '', 'Golemagg the Incinerator', 'golemagg', 'Two Core Ragers: an off-tank holds them away, nobody attacks them (they die with him). Pyroblast on random players, Earthquake at 10%.', 'Main tank on Golemagg (Magma Splash stacks); off-tank the two Ragers apart.', 'Heal the Pyroblasts; the main tank takes stacking fire damage.', 'Only Golemagg. Melee leave when he''s at 10% (Earthquake).'),
(409, 8, 'Molten Core', 'mc,molten core', '', 'Sulfuron Harbinger', 'sulfuron', 'Four Flamewaker Priests heal and cast Shadow Word: Pain: kill them first, interrupting Dark Mending.', 'Off-tanks on the priests; main tank on Sulfuron (Hand of Ragnaros knocks back).', 'Dispel Shadow Word: Pain.', 'Priests one by one, interrupt Dark Mending, then Sulfuron.'),
(409, 9, 'Molten Core', 'mc,molten core', '', 'Majordomo Executus', 'majordomo,domo', 'He submits when his eight guards die: four Flamewaker Healers, four Elites. He shields them with Magic Reflection and Damage Shield.', 'Tanks on the Elites; Majordomo teleports a tank into the fire now and then.', 'Heal the teleported tank.', 'Healers first, then Elites. Casters stop on Magic Reflection, melee on Damage Shield.'),
(409, 10, 'Molten Core', 'mc,molten core', '', 'Ragnaros', 'ragnaros,rag,raggy', 'Wrath of Ragnaros knocks back everyone in melee; with nobody in melee he hits the raid with Magma Blast. He submerges and eight Sons of Flame come: kill them.', 'Two tanks: one takes over after a knockback. Keep someone in melee always.', 'Fire resistance; heal the tanks through Elemental Fire.', 'Melee behind him, ranged spread. Kill the Sons of Flame when he submerges.'),
(249, 1, 'Onyxia''s Lair', 'ony,onyxia,onyxias lair', '', 'Onyxia', 'onyxia,ony', 'Phase 1 on the ground: breath in front, tail sweep behind. Phase 2 (65%) she flies: whelps pour out and Deep Breath crosses the room. Phase 3 (40%): Bellowing Roar fears, lava cracks.', 'Turn her so the raid stands at her flanks; in phase 3 Fear Ward and Tremor, take her back fast.', 'Stand at her side, never in the breath line; Fear Ward the tank in phase 3.', 'Flanks only. Phase 2: ranged on her, melee on whelps, run from Deep Breath. Phase 3: watch threat.'),
(469, 1, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Razorgore the Untamed', 'razorgore', 'Phase 1: one player controls Razorgore with the orb and breaks all 30 eggs while the raid holds the orcs and dragonkin. Phase 2: kill Razorgore (Conflagration, Fireball Volley).', 'Hold the adds in the corners in phase 1; take Razorgore in phase 2.', 'Protect the orb controller; heal the volleys in phase 2.', 'Kill adds before they reach the orb; then Razorgore.'),
(469, 2, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Vaelastrasz the Corrupt', 'vaelastrasz,vael', 'Burning Adrenaline on a mana user (and the tank in turn): they run away from the raid before it kills them. Essence of the Red gives everyone mana, energy and rage. Flame Breath in front.', 'Tanks rotate: the next one taunts when the current tank gets Adrenaline. Face him away.', 'Heal freely, your mana refills; heal the tanks hard.', 'Burn hard but watch threat; run out with Adrenaline. Never in front.'),
(469, 3, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Broodlord Lashlayer', 'broodlord,lashlayer', 'After the suppression room: Mortal Strike, Blast Wave, Knock Away.', 'Back to a wall; two tanks so a knock away doesn''t lose him.', 'Heal ahead of the mortal strikes.', 'From behind; watch threat after a knock away.'),
(469, 4, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Firemaw', 'firemaw', 'Flame Buffet stacks on everyone in line of sight; hide behind the pillar to drop stacks. Wing Buffet, Shadow Flame.', 'Tanks swap when stacks get high; Onyxia Scale Cloak for Shadow Flame.', 'Duck out of sight to drop stacks between heals.', 'Ranged step behind the pillar now and then to drop stacks.'),
(469, 5, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Ebonroc', 'ebonroc', 'Shadow of Ebonroc on the tank heals him when he hits: another tank taunts at once. Wing Buffet, Shadow Flame.', 'Second tank taunts as soon as the first gets Shadow of Ebonroc.', 'Heal both tanks.', 'From behind; watch threat during tank swaps.'),
(469, 6, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Flamegor', 'flamegor', 'Frenzy: hunters Tranquilizing Shot it at once. Fire Nova grows each frenzy, Wing Buffet, Shadow Flame.', 'Two tanks for the wing buffets.', 'Raid-wide fire damage grows if frenzies aren''t removed.', 'Hunters: Tranq Shot on every frenzy.'),
(469, 7, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Chromaggus', 'chromaggus,chromag', 'Two breaths from five (Time Lapse, Corrosive Acid, Incinerate, Frost Burn, Ignite Flesh): hide behind the door corner when he breathes. Brood Afflictions of five colours; Frenzy.', 'Tank him where the raid can hide from the breaths.', 'Hourglass Sand cures bronze; cure what you can, all five colours turn a player.', 'Hunters Tranq the frenzy; everyone out of line of sight on breaths.'),
(469, 8, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Lord Victor Nefarius', 'nefarius,victor nefarius', 'Phase 1: drakonids by colour flood both sides; kill 42 of them. Nefarius blinks, Shadow Bolts and fears.', 'Tanks on each side gather the drakonids.', 'Fear Ward the tanks.', 'Area attacks on the drakonids.'),
(469, 9, 'Blackwing Lair', 'bwl,blackwing lair,blackwing', '', 'Nefarian', 'nefarian,nef', 'Lands after 42 drakonids: Shadow Flame in front, Bellowing Roar fears, Veil of Shadow; class calls punish each class. At 20% the dead drakonids rise as bone constructs.', 'Face him away from the raid, Fear Ward and Onyxia Scale Cloak.', 'Decurse Veil of Shadow on the tank; react to the class calls.', 'Never in front; at 20% kill or area the bone constructs.'),
(309, 1, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'High Priestess Jeklik', 'jeklik,bat', 'Bat phase: bat swarms, Charge and silencing screech. Troll phase at half health: she heals (interrupt), and bat riders drop fire bombs.', 'Back to a wall; pick up the bat swarms.', 'Heal through the fire bombs; stay out of the fire.', 'Interrupt her Great Heal; kill the bats, step out of the fire.'),
(309, 2, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'High Priest Venoxis', 'venoxis,snake', 'Troll phase: Holy Nova, Holy Fire, Renew (dispel it). Snake phase at half health: poison clouds and Venom Spit. Four Razzashi Cobras guard him: kill them first.', 'Hold him; in snake form move him out of the clouds.', 'Dispel his Renew, cure poison.', 'Cobras first, interrupt Holy Fire; step out of the poison clouds.'),
(309, 3, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'High Priestess Mar''li', 'marli,spider', 'Troll phase: spider eggs hatch, Poison Bolt Volley, Drain Life. Spider phase: Enveloping Webs, Charge.', 'Hold her and the spiders; she drops threat in spider form.', 'Cure poison on everyone.', 'Kill the hatchlings, interrupt Drain Life.'),
(309, 4, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Bloodlord Mandokir', 'mandokir,raptor', 'Rides his raptor Ohgan. Threatening Gaze: whoever he watches must stand still or be killed. He levels up on kills; spirits revive the dead.', 'Off-tank Ohgan; main tank on Mandokir facing away (cleave).', 'Stop casting when he watches you.', 'Watched: stop casting and attacking and don''t move. Focus Mandokir while Ohgan stays off-tanked.'),
(309, 5, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Gri''lek', 'grilek,edge of madness', 'Edge of Madness: grows and fixates on a random player, Avatar makes him huge.', 'Pick him back up after each fixate.', 'Keep the fixated player alive.', 'Kite him if he fixates on you.'),
(309, 6, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Hazza''rah', 'hazzarah', 'Edge of Madness: summons Nightmare Illusions and puts players to sleep.', 'Grab the illusions.', 'Dispel the sleep.', 'Kill the illusions fast.'),
(309, 7, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Renataki', 'renataki', 'Edge of Madness: vanishes and ambushes random players, Thousand Blades.', 'Pick him back up when he reappears.', 'Heal the ambushed player.', 'Watch threat after his vanish.'),
(309, 8, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Wushoolay', 'wushoolay', 'Edge of Madness: Chain Lightning and Lightning Cloud.', 'Hold her.', 'Heal the chain lightning.', 'Spread out, step out of the clouds.'),
(309, 9, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Gahz''ranka', 'gahzranka', 'Fished up with Mudskunk Lure: Frost Breath in front, Massive Geyser throws players up.', 'Face it away from the raid.', 'Heal the falling damage.', 'From the sides.'),
(309, 10, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'High Priest Thekal', 'thekal,tiger', 'With Zealots Zath and Lor''Khan: all three must die within 10 seconds or they rise. Then Thekal''s tiger form: Force Punch, tigers join.', 'Three tanks on the three trolls; take Thekal again in tiger form.', 'Heal all three tanks.', 'Bring all three down together, then the tiger.'),
(309, 11, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'High Priestess Arlokk', 'arlokk,panther', 'Called with the gong. Marks a player for the panthers, vanishes and returns; panthers keep coming from the sides.', 'Grab the panthers; pick her up when she reappears.', 'Heal the marked player.', 'Kill panthers on the marked player; burn her when she''s out.'),
(309, 12, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Jin''do the Hexxer', 'jindo', 'Hex on the tank, Brain Wash totems mind control, Healing Wards, and Delusions: cursed players see shades only they can kill.', 'Off-tank takes over while the main tank is hexed.', 'Dispel the hex; decurse Delusions only after the shade dies.', 'Kill the Brain Wash totem and the Healing Ward at once; cursed players kill their shades.'),
(309, 13, 'Zul''Gurub', 'zg,zulgurub,zul gurub', '', 'Hakkar', 'hakkar,soulflayer', 'Blood Siphon drains everyone: be Poisoned Blood (from a Son of Hakkar) or you feed him. Corrupted Blood spreads, Cause Insanity, Will of Hakkar mind controls.', 'Two tanks; Cause Insanity drops one, the other taunts.', 'Keep the poisoned alive before Siphon; spread for Corrupted Blood.', 'Kill a Son of Hakkar before each Siphon and stand in its poison; spread out.'),
(509, 1, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'Kurinnaxx', 'kurinnaxx', 'Mortal Wound stacks on the tank, Sand Traps appear under players (move off them), he enrages at 30%.', 'Two tanks swap at about 5 Mortal Wound stacks.', 'Heal ahead of the mortal wounds.', 'Step off the sand traps; burn him in the enrage.'),
(509, 2, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'General Rajaxx', 'rajaxx,captain tuubid,waves', 'Seven waves of Qiraji led by captains, then Rajaxx: Thundercrash halves everyone''s health, Disarm.', 'Gather each wave on you; captains on their own tank.', 'Top everyone before Thundercrash.', 'Area attacks on the waves, the captain of each wave first.'),
(509, 3, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'Moam', 'moam', 'Drains mana from players to fill his own; at full mana he explodes. Every so often he turns to stone and three Mana Fiends spawn.', 'Off-tanks grab the Mana Fiends.', 'Drain Moam''s mana: Viper Sting, Mana Burn, Drain Mana.', 'Burn him fast; kill the Mana Fiends when he''s stone.'),
(509, 4, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'Buru the Gorger', 'buru', 'Fixates on a player and chases them: kite him over the eggs and blow them up near him. At 20% he hardens and takes more damage.', 'No real tank: the fixated player runs him over eggs.', 'Heal the egg blasts and the fixated player.', 'Break eggs when Buru is on them; burn him at 20%.'),
(509, 5, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'Ayamiss the Hunter', 'ayamiss,wasp', 'Flies at first: Stinger Spray, Poison Stinger, and paralyzes a player on the altar where larvae come to eat them. Lands at 70%.', 'Pick her up when she lands.', 'Cure poison; heal the sacrificed player.', 'Kill the larvae before they reach the altar; ranged on her while she flies.'),
(509, 6, 'Ruins of Ahn''Qiraj', 'aq20,ruins,ruins of ahnqiraj', '', 'Ossirian the Unscarred', 'ossirian', 'Immune to everything until he stands by a crystal: each crystal makes him weak to one school for a while. Tornadoes roam; War Stomp, Curse of Tongues.', 'Drag him to the next crystal before the weakness ends.', 'Decurse; dodge the tornadoes.', 'Use the school the crystal opens; stay away from the tornadoes.'),
(531, 1, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'The Prophet Skeram', 'skeram,prophet', 'Splits into three at 75%, 50% and 25%: kill the real one (the illusions die with it). Arcane Explosion, Earth Shock, and True Fulfillment mind controls.', 'One tank on each copy, spread on the platforms.', 'Crowd control or sheep the mind controlled.', 'Interrupt Arcane Explosion; find and burn the real Skeram.'),
(531, 2, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Lord Kri', 'kri,bug trio,bugs', 'The Bug Trio: Kri (cleave, poison cloud when he dies), Yauj (fears, heals the others) and Vem (charges, knock backs). Kill Kri and Yauj, Vem last.', 'Three tanks, one per bug.', 'Interrupt Yauj''s heals; heal through the poison.', 'Kri first away from the raid, Yauj second, Vem last.'),
(531, 3, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Princess Yauj', 'yauj', 'Bug Trio: fears and Great Heal on the others; her death releases brood bugs.', 'Fear Ward on her tank.', 'Heal through the fears.', 'Interrupt her heals; area attacks on her brood when she dies.'),
(531, 4, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Vem', 'vem', 'Bug Trio: Charge and Knock Away. He enrages when the others die: kill him last.', 'Hold him away from the raid.', 'Heal the charges.', 'Last.'),
(531, 5, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Battleguard Sartura', 'sartura', 'With three Sartura''s Royal Guards: all of them Whirlwind. Stun the guards, kill them, then Sartura. Enrages after 10 minutes.', 'One tank per guard and Sartura; pick them back up after a whirlwind.', 'Heal the whirlwinds, stay spread.', 'Stun the guards in turn; guards first, then Sartura.'),
(531, 6, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Fankriss the Unyielding', 'fankriss', 'Mortal Wound stacks on the tank; worms spawn at the tunnels and entangle and kill players fast.', 'Two or three tanks swap at Mortal Wound stacks.', 'Heal through the wounds.', 'Kill the spawned worms at once.'),
(531, 7, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Viscidus', 'viscidus', 'Freeze him with frost damage (200 frost hits), then shatter him with melee. He splits into globs: kill them before they rejoin. Poison bolt volley.', 'Hold him.', 'Cure poison; nature resistance.', 'Frost spells and frost weapons to freeze him, melee to shatter, then kill the globs.'),
(531, 8, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Princess Huhuran', 'huhuran', 'Wyvern Sting puts people to sleep, Acid Spit stacks on the tank, Noxious Poison; Frenzy and berserk at 30%.', 'Nature resistance; tanks swap if acid stacks high.', 'Nature resistance; heavy raid damage at 30%.', 'Hunters Tranq the frenzy; burn her from 30%.'),
(531, 9, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Emperor Vek''lor', 'veklor,twins,twin emperors', 'Twin Emperors: Vek''lor casts (Shadow Bolt, Blizzard, Arcane Burst), immune to physical damage; Vek''nilash fights in melee, immune to spells. They teleport and swap; kept close they heal.', 'A warlock tanks Vek''lor with Shadow Bolt; warriors take Vek''nilash. Swap sides after each teleport.', 'Stay out of Blizzard, keep spread; pace your mana.', 'Casters on Vek''lor, melee on Vek''nilash; keep the two apart.'),
(531, 10, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Emperor Vek''nilash', 'veknilash', 'Twin Emperors: Vek''nilash only takes physical damage, Uppercut, Unbalancing Strike. Bugs he touches explode (Mutate Bug).', 'Warrior tanks pick him up after each teleport.', 'Heal the tank through Unbalancing Strike.', 'Melee on Vek''nilash; casters on Vek''lor.'),
(531, 11, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'Ouro', 'ouro', 'Sand Blast in front, Sweep knocks back the melee. He submerges and pops up somewhere else; scarabs come out. Berserk at 20%.', 'Face him away; pick him up where he surfaces.', 'Heal the sweep and the sand blast.', 'Never in front; kill the scarabs; ranged pick him up when he surfaces.'),
(531, 12, 'Temple of Ahn''Qiraj', 'aq40,aq,temple of ahnqiraj,ahnqiraj', '', 'C''Thun', 'cthun', 'Phase 1: the eye''s Dark Glare sweeps the room, Eye Beam chains: spread in a circle 10 yards apart, kill Eye Tentacles. Phase 2: players are eaten into his stomach; kill the flesh tentacles inside.', 'Pick up the Giant Claw Tentacles.', 'Everyone spread; heal the eye beams.', 'Spread, move out of Dark Glare, tentacles first; in phase 2 the eaten kill the stomach tentacles.'),
(533, 1, 'Naxxramas', 'naxx,naxxramas', 'Spider', 'Anub''Rekhan', 'anubrekhan,anub', 'Locust Swarm: he walks slowly while the swarm shreds everyone near; kite him round the room. Impale in a line; Crypt Guards come.', 'Kite him during Locust Swarm; off-tank the Crypt Guards.', 'Stay out of the swarm; heal the impaled.', 'Kill the Crypt Guards; spread against Impale; never stand in the swarm.'),
(533, 2, 'Naxxramas', 'naxx,naxxramas', 'Spider', 'Grand Widow Faerlina', 'faerlina,widow', 'Enrages: a priest mind controls a Naxxramas Worshipper and sacrifices it (Widow''s Embrace) to stop the enrage. Rain of Fire, Poison Bolt Volley.', 'Tanks on the followers; main tank on Faerlina.', 'Cure poison, step out of Rain of Fire.', 'Kill the followers, leave the worshippers for the priests.'),
(533, 3, 'Naxxramas', 'naxx,naxxramas', 'Spider', 'Maexxna', 'maexxna', 'Web Wrap cocoons players on the wall (break them free), Web Spray stuns everyone every 40 seconds, Necrotic Poison cuts healing on the tank, enrage at 30%.', 'Cure the poison quickly; big hits after each web spray.', 'Top the tank before Web Spray; cure Necrotic Poison.', 'Ranged free the web-wrapped; area the spiderlings.');
INSERT INTO `companion_boss_tactics` (`map`, `sort`, `instance`, `instance_aliases`, `wing`, `boss`, `aliases`, `general`, `tank`, `healer`, `dps`) VALUES
(533, 4, 'Naxxramas', 'naxx,naxxramas', 'Plague', 'Noth the Plaguebringer', 'noth', 'Blinks (threat reset) and curses everyone; teleports to the balcony and skeleton waves come.', 'Pick him up after each blink; hold the skeletons.', 'Decurse at once.', 'Watch threat after blinks; area the skeletons.'),
(533, 5, 'Naxxramas', 'naxx,naxxramas', 'Plague', 'Heigan the Unclean', 'heigan,dance', 'The safety dance: eruptions sweep the room''s four zones in turn; move to the safe zone. On the platform phase everyone dances faster.', 'Dance with him through the zones.', 'Healers on the platform; cure disease.', 'Follow the dance; nobody stands in an erupting zone.'),
(533, 6, 'Naxxramas', 'naxx,naxxramas', 'Plague', 'Loatheb', 'loatheb', 'Corrupted Mind lets each healer cast one heal a minute: healers take turns. Spores spawn, standing in a spore cloud gives crits. Inevitable Doom kills slowly later on.', 'Use healthstones and potions; shadow protection helps.', 'Follow the healing rotation: one big heal when it is your turn.', 'Rotate through the spores for the crit bonus.'),
(533, 7, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Instructor Razuvious', 'razuvious', 'Only Death Knight Understudies, mind controlled by priests, can tank him. Disrupting Shout drains mana; Unbalancing Strike.', 'Priests control the understudies and use their taunt and shield wall in turn.', 'Stand out of shout range.', 'Burn him while the understudies tank.'),
(533, 8, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Gothik the Harvester', 'gothik', 'Split the raid on both sides of the gate: live adds come on one side, their spirits on the other. The gate opens later; then Gothik comes down.', 'Tanks on both sides gather the adds.', 'Heal your own side.', 'Kill live adds on their side; spirits on the dead side.'),
(533, 9, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Thane Korth''azz', 'korthazz,four horsemen,horsemen', 'The Four Horsemen: each leaves marks that stack on everyone near; tanks rotate between the four corners. Korth''azz casts Meteor on his tank''s group.', 'Rotate corners at 3 to 4 marks.', 'Rotate with the tanks.', 'Everyone near Korth''azz shares his Meteor.'),
(533, 10, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Highlord Mograine', 'highlord mograine', 'Four Horsemen: Righteous Fire on his tank; marks stack.', 'Rotate at 3 to 4 marks.', 'Heal the fire.', 'Melee kill him with Korth''azz in turn.'),
(533, 11, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Lady Blaumeux', 'blaumeux', 'Four Horsemen: Void Zones under players. Kill her from range.', 'Rotate at 3 to 4 marks.', 'Step out of Void Zones.', 'Out of Void Zones.'),
(533, 12, 'Naxxramas', 'naxx,naxxramas', 'Military', 'Sir Zeliek', 'zeliek', 'Four Horsemen: Holy Wrath chains between players standing close.', 'Rotate at 3 to 4 marks.', 'Spread out near him.', 'Ranged spread around him.'),
(533, 13, 'Naxxramas', 'naxx,naxxramas', 'Construct', 'Patchwerk', 'patchwerk,patch', 'Hateful Strike hits the melee with the most health besides the tank: three or four tanks soak it. Pure damage race, enrage at 5%.', 'Soak Hateful Strike: stay in melee with the highest health.', 'Heal the soakers hard.', 'Burn him; melee stay below the soakers'' health.'),
(533, 14, 'Naxxramas', 'naxx,naxxramas', 'Construct', 'Grobbulus', 'grobbulus,grob', 'Mutating Injection: that player runs to the side to drop a poison cloud. Slime Spray in front spawns oozes.', 'Kite him slowly round the room away from the clouds; face him away.', 'Dispel the injection only once the player is out.', 'Out of his front; kill the oozes.'),
(533, 15, 'Naxxramas', 'naxx,naxxramas', 'Construct', 'Gluth', 'gluth', 'Zombie Chows walk in and feed him; Decimate drops everyone to 5%. Mortal Wound on the tank; Frenzy.', 'Two tanks swap at Mortal Wound stacks.', 'Heal the raid after each Decimate.', 'Kite and kill the zombies; hunters Tranq the frenzy.'),
(533, 16, 'Naxxramas', 'naxx,naxxramas', 'Construct', 'Thaddius', 'thaddius,stalagg,feugen', 'First Stalagg and Feugen on two platforms die together. Thaddius: Polarity Shift gives + or - charge: pluses stand left, minuses right; mixed charges hurt.', 'Hold the two first, then Thaddius.', 'Move with your charge.', 'Kill both platform bosses together; after each shift move to your side.'),
(533, 17, 'Naxxramas', 'naxx,naxxramas', 'Frostwyrm Lair', 'Sapphiron', 'sapphiron,sapph', 'Frost Aura drains everyone, Life Drain (decurse), Blizzard. In the air he Ice Bolts players into blocks: hide behind them from Frost Breath.', 'Frost resistance; face him away.', 'Decurse Life Drain; frost resistance.', 'Out of Blizzard; hide behind an ice block for the breath.'),
(533, 18, 'Naxxramas', 'naxx,naxxramas', 'Frostwyrm Lair', 'Kel''Thuzad', 'kelthuzad,kt', 'Phase 1: waves of undead come to the middle. Phase 2: Frostbolt (interrupt), Frost Blast, Mana Detonation, Shadow Fissure, Chains of Kel''Thuzad mind control. Phase 3: guardians.', 'Off-tanks take the Guardians of Icecrown in phase 3.', 'Spread; mana users with detonation run out.', 'Interrupt Frostbolt; step out of Shadow Fissures; crowd control the chained.'),
(0, 1, 'Eastern Kingdoms', '', '', 'Lord Kazzak', 'kazzak', 'Blasted Lands world boss: Shadow Bolt Volley, Mark of Kazzak drains mana then explodes, Twisted Reflection heals him, Capture Soul heals him on every death. Berserk after 3 minutes.', 'Hold him in the open, two tanks.', 'Dispel Twisted Reflection; keep everyone alive, deaths heal him.', 'A race against 3 minutes; marked players run out.'),
(0, 2, 'Eastern Kingdoms', '', '', 'Emeriss', 'emeriss', 'Dragon of Nightmare: Noxious Breath in front, tail sweep behind, sleeping fog, players who die grow mushrooms. Volatile Infection on a player.', 'Face her away from the raid, nature resistance.', 'Out of the green fog.', 'Flanks only; nobody dies near the raid.'),
(0, 3, 'Eastern Kingdoms', '', '', 'Lethon', 'lethon', 'Dragon of Nightmare: Shadow Bolt Whirl, spawns shades from every player that heal him.', 'Face him away.', 'Out of the green fog.', 'Kill the shades before they reach him.'),
(0, 4, 'Eastern Kingdoms', '', '', 'Taerar', 'taerar', 'Dragon of Nightmare: Arcane Blast, Bellowing Roar fears, and splits into three shades.', 'Fear Ward; tanks for the shades.', 'Out of the green fog.', 'Kill the shades when he splits.'),
(0, 5, 'Eastern Kingdoms', '', '', 'Ysondre', 'ysondre', 'Dragon of Nightmare: Lightning Wave chains, calls Demented Druid Spirits.', 'Face her away; pick up the spirits.', 'Out of the green fog.', 'Spread for the lightning; kill the spirits.'),
(1, 1, 'Kalimdor', '', '', 'Azuregos', 'azuregos', 'Blue dragon in Azshara: Mark of Frost, Frost Breath in front, Mana Storm, and he teleports everyone near to him (threat reset).', 'Face him away; take him back after each teleport.', 'Out of the Mana Storm.', 'Stop after his teleport until the tank has him again.'),
(1, 2, 'Kalimdor', '', '', 'Emeriss', 'emeriss', 'Dragon of Nightmare: Noxious Breath in front, tail sweep behind, sleeping fog, players who die grow mushrooms.', 'Face her away, nature resistance.', 'Out of the green fog.', 'Flanks only.'),
(1, 3, 'Kalimdor', '', '', 'Lethon', 'lethon', 'Dragon of Nightmare: Shadow Bolt Whirl, shades from every player heal him.', 'Face him away.', 'Out of the green fog.', 'Kill the shades before they reach him.'),
(1, 4, 'Kalimdor', '', '', 'Taerar', 'taerar', 'Dragon of Nightmare: Arcane Blast, a fear, and he splits into three shades.', 'Fear Ward; tanks for the shades.', 'Out of the green fog.', 'Kill the shades when he splits.'),
(1, 5, 'Kalimdor', '', '', 'Ysondre', 'ysondre', 'Dragon of Nightmare: Lightning Wave chains, calls Demented Druid Spirits.', 'Face her away; pick up the spirits.', 'Out of the green fog.', 'Spread for the lightning.');
